def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    threat_bids = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                req = opp.get('water_requirement', WATER_REQ)
                if req >= WATER_REQ:
                    threat_bids.append(bid)

    if not alive:
        return max(0.0, min(budget, 18.0 if hp > 3 else 40.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_threat = max(threat_bids) if threat_bids else highest_prev

    competitors = int(supply // WATER_REQ)
    if competitors < 1:
        competitors = 1

    urgent = hp <= 2 or no_water >= 1
    very_urgent = hp <= 1 or no_water >= 2

    if competitors >= 2:
        base = 22.0
        if highest_threat > 0:
            base = min(highest_threat * 0.58, 52.0)
        if urgent:
            base = max(base, 48.0)
        if very_urgent:
            base = max(base, 66.0)
        return max(0.0, min(budget, base))

    target = highest_threat + 2.0 if highest_threat > 0 else 61.0

    if highest_prev >= 120:
        if urgent:
            target = max(target, 96.0)
        else:
            target = min(target, 74.0)
    elif highest_prev >= 85:
        if urgent:
            target = max(target, highest_prev + 3.0)
        else:
            target = max(72.0, highest_threat + 2.0)
    else:
        if urgent:
            target = max(target, 78.0)
        else:
            target = max(target, 64.0)

    if budget < target:
        if urgent:
            return max(0.0, budget)
        return max(0.0, min(budget, max(18.0, budget * 0.55)))

    reserve_floor = DAILY_SALARY * 1.2
    if budget > reserve_floor and not urgent:
        target = min(target, budget - reserve_floor + target * 0.15)

    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp is not None and bool(opp.get('alive', False)):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids to infer pressure.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Identify likely low-contest opponents by yesterday budget after.
    # If an opponent ended with extremely low budget, assume they will not overbid today.
    low_budget_opps = 0
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b_after = prev.get('budget_after', None)
        if b_after is not None:
            try:
                if float(b_after) <= 5.0:
                    low_budget_opps += 1
            except Exception:
                pass

    # Base bid target: undercut the highest yesterday bid while still competing.
    # Use current supply to scale aggressiveness (higher supply => less need to overbid).
    # Ensure indices are int-safe if we compute discrete levels.
    supply_level = int(round((supply - MIN_SUPPLY) / max(1e-9, (MAX_SUPPLY - MIN_SUPPLY)) * 4))
    if supply_level < 0:
        supply_level = 0
    if supply_level > 4:
        supply_level = 4

    # Supply factor: when supply is low, bid more.
    supply_factors = [1.10, 1.05, 1.00, 0.95, 0.90]
    factor = supply_factors[supply_level]

    # Pressure logic from yesterday.
    # If someone bid very high yesterday, Alex-like contest: bid moderately below.
    if highest_prev_bid >= DAILY_SALARY * 0.70:
        # If my HP is critical, go higher.
        if my_hp <= 2 or my_no_water_days >= 1:
            target = min(my_budget, (highest_prev_bid * 0.60 + 25.0) * factor)
        else:
            target = min(my_budget, (highest_prev_bid * 0.50 + 20.0) * factor)
    else:
        # Otherwise bid enough to secure water but avoid wasting budget.
        if my_hp <= 2 or my_no_water_days >= 1:
            target = min(my_budget, DAILY_SALARY * 0.55 * factor)
        else:
            # If many opponents likely low-budget, we can bid lower.
            if low_budget_opps >= 1:
                target = min(my_budget, DAILY_SALARY * 0.42 * factor)
            else:
                target = min(my_budget, DAILY_SALARY * 0.48 * factor)

    # Safety clamps: never bid negative; avoid overshooting budget.
    if target < 0.0:
        target = 0.0
    if target > my_budget:
        target = my_budget

    # If we can afford it, keep a small minimum bid to avoid being completely outbid.
    min_bid = 10.0
    if target < min_bid and my_budget >= min_bid:
        target = min_bid

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    supply = day_context['supply']
    day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Compute yesterday's bids from traces
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid: proportional to requirement
    available_water = supply
    need_water = WATER_REQ
    urgency = 1.0 if my_hp <= 2 or no_water_days >= 2 else (my_hp / 10.0)
    base_bid = min(my_budget, max(DAILY_SALARY * 0.3, DAILY_SALARY * (need_water / MAX_SUPPLY) * (1.0 - urgency * 0.3)))

    if yesterday_bids:
        avg_yesterday = sum(yesterday_bids) / len(yesterday_bids)
        max_yesterday = max(yesterday_bids)
        # If opponents have low budget or low hp, they may bid low today
        weak_opponent_exists = any(o['budget'] < DAILY_SALARY * 0.5 or o['hp'] <= 2 for o in alive_opponents.values())
        if weak_opponent_exists:
            # Exploit: bid slightly above average to secure water cheaply
            target = max(base_bid, avg_yesterday * 1.05)
        else:
            # All strong: need to outbid highest yesterday if supply low
            if supply <= 18:
                target = max_yesterday + 2.0
            else:
                target = max(base_bid, avg_yesterday * 1.1)
    else:
        target = base_bid

    # Ensure we don't exceed budget and respect extreme needs
    if my_hp <= 1:
        target = min(my_budget, DAILY_SALARY * 0.95)
    elif my_hp <= 3 or no_water_days >= 1:
        target = max(target, DAILY_SALARY * 0.7)

    # Cap at budget
    final_bid = min(my_budget, max(0, target))
    return int(final_bid)
